def recuperar_domain_principal():

    html = requests.get("https://theporndude.com/pt").content
    soup = BeautifulSoup(html, 'html.parser')

    

    lista_items = soup.find_all("li")
    
    for item in lista_items:
            # Procurar a tag <a> dentro de cada <li>
            link = item.find('a')
            if link and link.get('href'):  # Verifica se há um <a> e se tem atributo href
                content.append(link.get('href'))


def recuperar_domain_subsite(subsite):
    html2 = requests.get(subsite).content
    soup2 = BeautifulSoup(html2, 'html.parser')
        
    lista_items2 = soup2.find('a', class_='link-analytics')
    link = lista_items2.get('href')
    return link
    


    
    


